&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Faiblesses&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ature-Empaill&#233;e,-Arch&#233;type.html&quot; title=&quot;Cr&#233;ature empaill&#233;e, arch&#233;type&quot;&gt;d&#233;faut&lt;/a&gt; (coutures grossi&#232;res), &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ature-Empaill&#233;e,-Arch&#233;type.html&quot; title=&quot;Cr&#233;ature empaill&#233;e, arch&#233;type&quot;&gt;vuln&#233;rabilit&#233; aux d&#233;g&#226;ts tranchants&lt;/a&gt;
